import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type SendTaskFailureInput = {
  /**
   * The token that represents this task. Task tokens are generated by Step Functions when tasks are
   * assigned to a worker, or in the context object when a workflow enters a task state. See
   * GetActivityTaskOutput$taskToken.
   */
  taskToken: string;
  /** The error code of the failure. */
  error?: string;
  /** A more detailed explanation of the cause of the failure. */
  cause?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const sendTaskFailureInputSchema: Schema<SendTaskFailureInput> = s.object<SendTaskFailureInput>(
  {
    taskToken: s.string(),
    error: s.optional(s.string()),
    cause: s.optional(s.string()),
  },
  { additionalProperties: s.json() },
);
